"""Generate an N-Husky fleet world for the constraint-buffer scale probe.

Faithful to projects/samples/demos/worlds/physics/newton_husky_swarm_drive.wbt
(same URDF, same drive_forward controller, same 12 m y-spacing, same
spawn z=0.3) but parameterised on N and on the Newton knobs under test.
"""

from __future__ import annotations

import argparse
import os

HDR = """#OMNISIM R2025a utf8

# GENERATED by _scratch/wheelscale/gen_world.py -- measurement scratch, not a demo.

EXTERNPROTO "omnisim://projects/objects/floors/protos/RectangleArena.proto"
EXTERNPROTO "omnisim://projects/appearances/protos/Asphalt.proto"
EXTERNPROTO "omnisim://projects/objects/backgrounds/protos/OmniSimSky.proto"
EXTERNPROTO "omnisim://projects/objects/lights/protos/OmniSimSun.proto"
EXTERNPROTO "omnisim://projects/objects/lights/protos/OmniSimSunMarker.proto"

WorldInfo {{
  basicTimeStep {dt}
  title "wheelscale N={n}"
{knobs}}}
Viewpoint {{
  orientation 0.000000 1.000000 0.000000 1.570796
  position -7.000 0.000 {campos:.1f}
}}
OmniSimSky {{ }}
DEF SUN OmniSimSun {{ }}
DEF SUN_MARKER OmniSimSunMarker {{ }}

RectangleArena {{
  floorSize {arena} {arena}
  wallHeight 0.5
  floorAppearance Asphalt {{
    colorOverride 0.55 0.57 0.60
  }}
}}

DEF PROBE Robot {{
  name "probe"
  controller "fleet_probe"
  supervisor TRUE
}}
"""

BOT = """
DEF BOT{i} URDFRobot {{
  url "{url}"
  translation {x} {y} {z}
  name "bot_{i}"
  controller "{ctrl}"
  physicsBackend "newton"
}}
"""


BUMP = """
DEF BUMP{i} Solid {{
  translation {x} {y} {hz}
  name "bump_{i}"
  children [
    Shape {{
      appearance PBRAppearance {{ baseColor 0.8 0.3 0.1 roughness 1 metalness 0 }}
      geometry Box {{ size 0.30 2.0 {h} }}
    }}
  ]
  boundingObject Box {{ size 0.30 2.0 {h} }}
}}
"""


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("-n", type=int, required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--solver", default="mujoco")
    ap.add_argument("--njmax", type=int, default=0)
    ap.add_argument("--nconmax", type=int, default=0)
    ap.add_argument("--substeps", type=int, default=0)
    ap.add_argument("--spacing", type=float, default=12.0)
    ap.add_argument("--z", type=float, default=0.3)
    ap.add_argument("--dt", type=int, default=16)
    ap.add_argument("--ctrl", default="drive_forward")
    ap.add_argument("--arena", type=int, default=0)
    ap.add_argument("--statics", type=int, default=0)
    ap.add_argument("--bump", type=float, default=0.0)
    ap.add_argument("--bump-x", type=float, default=3.0)
    ap.add_argument("--depth", default="../../../projects/robots/clearpath/"
                                        "husky_description/urdf/husky.urdf")
    a = ap.parse_args()

    knobs = ""
    if a.solver:
        knobs += '  newtonSolver "%s"\n' % a.solver
    if a.substeps:
        knobs += "  newtonSubsteps %d\n" % a.substeps
    if a.njmax:
        knobs += "  newtonNjmax %d\n" % a.njmax
    if a.nconmax:
        knobs += "  newtonNconmax %d\n" % a.nconmax

    span = (a.n - 1) * a.spacing
    arena = a.arena or max(100, int(span + 40))
    if a.statics:
        knobs += "  newtonStatics TRUE\n"
    body = HDR.format(n=a.n, dt=a.dt, knobs=knobs, arena=arena,
                      campos=max(220.0, span * 2.2))
    y0 = -span / 2.0
    for i in range(a.n):
        y = round(y0 + i * a.spacing, 3)
        body += BOT.format(i=i, url=a.depth, x=-7, y=y, z=a.z, ctrl=a.ctrl)
        if a.bump > 0:
            body += BUMP.format(i=i, x=-7 + a.bump_x, y=y, h=a.bump,
                                hz=a.bump / 2.0)
    os.makedirs(os.path.dirname(os.path.abspath(a.out)), exist_ok=True)
    with open(a.out, "w") as f:
        f.write(body)
    print(a.out)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
